"""Private object bytes. Keys are generated by the Vault service, never by callers."""

import os
import secrets
from pathlib import Path, PurePosixPath
from typing import Protocol

from app.core.config import settings


class ObjectStorage(Protocol):
    def put(self, key: str, data: bytes, content_type: str) -> None: ...
    def get(self, key: str) -> bytes: ...
    def delete(self, key: str) -> None: ...


def safe_key(key: str) -> PurePosixPath:
    path = PurePosixPath(key)
    if path.is_absolute() or not key or len(key) > 300 or any(part in {"", ".", ".."} for part in path.parts):
        raise ValueError("Invalid storage key")
    return path


class LocalStorage:
    def __init__(self, root: str):
        self.root = Path(root).resolve()

    def path_for(self, key: str) -> Path:
        path = self.root.joinpath(*safe_key(key).parts).resolve()
        if not path.is_relative_to(self.root):
            raise ValueError("Storage key escapes root")
        return path

    def put(self, key: str, data: bytes, content_type: str) -> None:
        path = self.path_for(key)
        path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        if path.exists():
            raise FileExistsError("Object key already exists")
        temporary = path.with_name(path.name + "." + secrets.token_hex(8) + ".tmp")
        try:
            with temporary.open("xb") as output:
                output.write(data)
                output.flush()
                os.fsync(output.fileno())
            os.replace(temporary, path)
        finally:
            temporary.unlink(missing_ok=True)

    def get(self, key: str) -> bytes:
        return self.path_for(key).read_bytes()

    def delete(self, key: str) -> None:
        self.path_for(key).unlink(missing_ok=True)


class S3Storage:
    def __init__(self, bucket: str, endpoint_url: str | None, region: str):
        import boto3

        self.bucket = bucket
        self.client = boto3.client("s3", endpoint_url=endpoint_url, region_name=region)

    def put(self, key: str, data: bytes, content_type: str) -> None:
        safe_key(key)
        self.client.put_object(Bucket=self.bucket, Key=key, Body=data, ContentType=content_type)

    def get(self, key: str) -> bytes:
        safe_key(key)
        return self.client.get_object(Bucket=self.bucket, Key=key)["Body"].read()

    def delete(self, key: str) -> None:
        safe_key(key)
        self.client.delete_object(Bucket=self.bucket, Key=key)


def get_storage() -> ObjectStorage:
    if settings.storage_backend == "local":
        return LocalStorage(settings.storage_local_path)
    if not settings.s3_bucket:
        raise RuntimeError("S3_BUCKET is required for S3 storage")
    return S3Storage(settings.s3_bucket, settings.s3_endpoint_url, settings.s3_region)
